import{_ as s,o as e,c as n,a2 as i}from"./chunks/framework.CNfFRqmr.js";const k=JSON.parse(`{"title":"Sandbox System","description":"harness9's Sandbox system runs all tool calls inside a Docker container, providing OS-level isolation — independent p...","frontmatter":{"title":"Sandbox System","description":"harness9's Sandbox system runs all tool calls inside a Docker container, providing OS-level isolation — independent p..."},"headers":[],"relativePath":"docs/sandbox.md","filePath":"docs/sandbox.md"}`),t={name:"docs/sandbox.md"};function l(r,a,o,d,p,h){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="sandbox-system" tabindex="-1">Sandbox System <a class="header-anchor" href="#sandbox-system" aria-label="Permalink to &quot;Sandbox System&quot;">​</a></h1><p>harness9&#39;s Sandbox system runs all tool calls inside a Docker container, providing OS-level isolation — independent process space, capability dropping, resource quotas — while remaining completely transparent to the Agent: the tool interface stays identical and behavior is fully consistent whether Sandbox is enabled or not.</p><hr><h2 id="why-do-we-need-sandbox" tabindex="-1">Why do we need Sandbox? <a class="header-anchor" href="#why-do-we-need-sandbox" aria-label="Permalink to &quot;Why do we need Sandbox?&quot;">​</a></h2><p>By default, harness9&#39;s tools (bash, read_file, etc.) execute directly in the host process, without container-level isolation. This is safe enough for local development, but stronger isolation is needed in the following scenarios:</p><ul><li>The Agent executes untrusted code or scripts</li><li>Multiple users share the same machine</li><li>Production deployments that need resource quota protection</li></ul><hr><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Confirm Docker is running</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Enable Sandbox in .env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;SANDBOX_ENABLED=true&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Start harness9</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness9</span></span></code></pre></div><p>Once enabled, a SandboxBar appears below the TUI StatusBar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>model: deepseek-v4-pro  |  ~/project  |  session: ...  |  ctx: 12K/256K (5%)</span></span>
<span class="line"><span>[Sandbox] 3a2f (main) Running</span></span>
<span class="line"><span>&gt; &gt; Enter a task...</span></span></code></pre></div><hr><h2 id="architecture-design" tabindex="-1">Architecture Design <a class="header-anchor" href="#architecture-design" aria-label="Permalink to &quot;Architecture Design&quot;">​</a></h2><h3 id="overall-structure" tabindex="-1">Overall Structure <a class="header-anchor" href="#overall-structure" aria-label="Permalink to &quot;Overall Structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>internal/sandbox/</span></span>
<span class="line"><span>├── config.go              # SandboxConfig (read from environment variables)</span></span>
<span class="line"><span>├── environment.go         # Environment interface</span></span>
<span class="line"><span>├── local_environment.go   # LocalEnvironment (default when Sandbox is off)</span></span>
<span class="line"><span>├── docker_environment.go  # DockerEnvironment (docker exec routing)</span></span>
<span class="line"><span>├── container.go           # Container five-state lifecycle state machine</span></span>
<span class="line"><span>└── manager.go             # Manager (concurrent Sandbox management)</span></span></code></pre></div><h3 id="environment-interface" tabindex="-1">Environment Interface <a class="header-anchor" href="#environment-interface" aria-label="Permalink to &quot;Environment Interface&quot;">​</a></h3><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Environment</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> interface</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    RunBash</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">cmd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">workDir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ReadFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ([]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">byte</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    WriteFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> []</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">byte</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Close</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ctx</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Context</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">error</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Two implementations:</p><ul><li><strong>LocalEnvironment</strong>: process-level, used by default when <code>SANDBOX_ENABLED=false</code>, behavior is fully identical to before Sandbox was introduced</li><li><strong>DockerEnvironment</strong>: container-level, <code>bash</code> commands are routed into the container via <code>docker exec</code>, file I/O is shared with the container via bind mount</li></ul><h3 id="tool-routing" tabindex="-1">Tool Routing <a class="header-anchor" href="#tool-routing" aria-label="Permalink to &quot;Tool Routing&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLM issues ToolCall &quot;bash&quot;</span></span>
<span class="line"><span>  → BashTool.Execute(ctx, args)</span></span>
<span class="line"><span>      ├── env == nil → exec.Command(&quot;bash&quot;, &quot;-c&quot;, cmd)    [Sandbox off]</span></span>
<span class="line"><span>      └── env != nil → env.RunBash() → docker exec …      [Sandbox on]</span></span></code></pre></div><p>File tools (read_file / write_file / edit_file) share the workDir via bind mount, operating directly on the host side, consistent with the in-container view.</p><h3 id="container-lifecycle" tabindex="-1">Container Lifecycle <a class="header-anchor" href="#container-lifecycle" aria-label="Permalink to &quot;Container Lifecycle&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         Creation request</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>        [Pending]     ← docker run issued, waiting for readiness</span></span>
<span class="line"><span>            ↓ docker inspect Running=true</span></span>
<span class="line"><span>        [Running]     ← accepts tool calls</span></span>
<span class="line"><span>            ↓ Close() / Agent exits</span></span>
<span class="line"><span>       [Stopping]     ← docker stop -t 5</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>      [Terminated]    ← docker rm completed</span></span>
<span class="line"><span></span></span>
<span class="line"><span>   Any state → [Failed]  ← docker command error / timeout</span></span></code></pre></div><h3 id="manager-concurrent-sandbox-management" tabindex="-1">Manager: Concurrent Sandbox Management <a class="header-anchor" href="#manager-concurrent-sandbox-management" aria-label="Permalink to &quot;Manager: Concurrent Sandbox Management&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Manager (singleton)</span></span>
<span class="line"><span>  ├── Create(ctx, workDir)   → Container + DockerEnvironment</span></span>
<span class="line"><span>  ├── Destroy(ctx, id)       → stop and remove the specified Container</span></span>
<span class="line"><span>  ├── DestroyAll(ctx)        → concurrently stop all Containers (called on defer exit)</span></span>
<span class="line"><span>  ├── ReapOrphans(ctx)       → clean up orphaned containers left over from a crash (called once at startup)</span></span>
<span class="line"><span>  └── ListAll()              → []SandboxInfo read-only snapshot (data source for TUI SandboxBar)</span></span></code></pre></div><hr><h2 id="security-hardening" tabindex="-1">Security Hardening <a class="header-anchor" href="#security-hardening" aria-label="Permalink to &quot;Security Hardening&quot;">​</a></h2><p>Every container is started with the following parameters, following the HermesAgent DockerEnvironment security standard as a reference:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--cap-drop all</code></td><td>—</td><td>Drop all Linux Capabilities</td></tr><tr><td><code>--cap-add DAC_OVERRIDE</code></td><td>—</td><td>File permission bypass (needed for package manager writes)</td></tr><tr><td><code>--cap-add SETUID</code></td><td>—</td><td>Allow apt-get to drop privileges to the <code>_apt</code> user</td></tr><tr><td><code>--cap-add SETGID</code></td><td>—</td><td>Allow apt-get to switch groups (works together with SETUID)</td></tr><tr><td><code>--security-opt no-new-privileges:true</code></td><td>—</td><td>Disallow setuid privilege escalation</td></tr><tr><td><code>--pids-limit</code></td><td>256</td><td>Prevent fork bombs</td></tr><tr><td><code>--tmpfs /tmp</code></td><td>256m,nosuid,noexec,nodev</td><td>Temp directory isolation</td></tr><tr><td>bind mount</td><td><code>workDir</code></td><td>Host and container share the working directory</td></tr></tbody></table><hr><h2 id="concurrent-isolation-model" tabindex="-1">Concurrent Isolation Model <a class="header-anchor" href="#concurrent-isolation-model" aria-label="Permalink to &quot;Concurrent Isolation Model&quot;">​</a></h2><p>Every Agent (including Sub-Agents) has its own independent Sandbox container:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main agent Sandbox (main)</span></span>
<span class="line"><span>  ├── workDir bind mount</span></span>
<span class="line"><span>  └── independent process space, independent tmpfs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sub-Agent A Sandbox (sub-1)           ← Created when the task starts, destroyed when it ends</span></span>
<span class="line"><span>Sub-Agent B Sandbox (sub-2)           ← independent container, does not affect others</span></span></code></pre></div><p><strong>Security constraint</strong>: a Sub-Agent&#39;s Sandbox inherits the parent Manager&#39;s configuration (same image, same resource limits) and cannot escalate privileges.</p><hr><h2 id="tui-sandboxbar" tabindex="-1">TUI SandboxBar <a class="header-anchor" href="#tui-sandboxbar" aria-label="Permalink to &quot;TUI SandboxBar&quot;">​</a></h2><p>When there are active Sandboxes, the SandboxBar is automatically displayed below the TUI StatusBar:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Sandbox] 3a2f (main) Running │ 7b1c (sub-1) Running │ 9d4e (sub-2) Pending</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Color</th><th>Status</th></tr></thead><tbody><tr><td>Green</td><td>Running (operating normally)</td></tr><tr><td>Yellow</td><td>Pending (starting up)</td></tr><tr><td>Gray</td><td>Stopping / Terminated</td></tr><tr><td>Red</td><td>Failed</td></tr></tbody></table><p>The SandboxBar is automatically hidden when the terminal width is insufficient, to avoid line wrapping breaking the layout.</p><hr><h2 id="configuration-parameters" tabindex="-1">Configuration Parameters <a class="header-anchor" href="#configuration-parameters" aria-label="Permalink to &quot;Configuration Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Environment Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>SANDBOX_ENABLED</code></td><td><code>false</code></td><td>Whether to enable Docker Sandbox</td></tr><tr><td><code>SANDBOX_IMAGE</code></td><td><code>ubuntu:22.04</code></td><td>Container image</td></tr><tr><td><code>SANDBOX_CPUS</code></td><td><code>1.0</code></td><td>CPU limit (docker --cpus)</td></tr><tr><td><code>SANDBOX_MEMORY</code></td><td><code>512m</code></td><td>Memory limit (docker --memory)</td></tr></tbody></table><p>Set in the <code>.env</code> file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SANDBOX_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SANDBOX_IMAGE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ubuntu:22.04</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SANDBOX_MEMORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1g</span></span></code></pre></div><hr><h2 id="orphaned-container-reclamation" tabindex="-1">Orphaned Container Reclamation <a class="header-anchor" href="#orphaned-container-reclamation" aria-label="Permalink to &quot;Orphaned Container Reclamation&quot;">​</a></h2><p>harness9 tags all managed containers with <code>label=harness9=1</code>. If the process crashes unexpectedly, leftover containers are automatically cleaned up by <code>Manager.ReapOrphans()</code> on the next startup:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Equivalent operation (executed internally by harness9)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> label=harness9=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=exited</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {{.ID}}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xargs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span></span></code></pre></div><hr><h2 id="implementation-references" tabindex="-1">Implementation References <a class="header-anchor" href="#implementation-references" aria-label="Permalink to &quot;Implementation References&quot;">​</a></h2><p>The Sandbox system draws on best practices from mainstream frameworks:</p><table tabindex="0"><thead><tr><th>Framework</th><th>What was borrowed</th></tr></thead><tbody><tr><td>HermesAgent</td><td>Docker security hardening parameters (cap-drop/no-new-privileges/pids-limit/tmpfs), orphaned container reclamation</td></tr><tr><td>OpenHarness</td><td>path_validator path validation</td></tr><tr><td>OpenSandbox</td><td>Seven-state lifecycle model (simplified to five states), execd communication pattern (simplified to docker exec)</td></tr></tbody></table><p>See the <a href="https://github.com/ZhangShenao/harness9/blob/master/docs/%E8%AE%BE%E8%AE%A1%E8%A7%84%E6%A0%BC/2026-06-05-sandbox-design.md" target="_blank" rel="noreferrer">Sandbox System Design Spec</a> and the <a href="https://github.com/ZhangShenao/harness9/blob/master/docs/%E6%8A%80%E6%9C%AF%E8%B0%83%E7%A0%94/sandbox-design-research.md" target="_blank" rel="noreferrer">Research Report</a> for more detail.</p>`,55)])])}const g=s(t,[["render",l]]);export{k as __pageData,g as default};
